<script>export let id = 'range';
export let min;
export let max;
export let value;
export let step;
export let size;
let inputClass = 'w-full bg-gray-200 rounded-lg appearance-none cursor-pointer dark:bg-gray-700 ';
if (size === 'small') {
    inputClass += 'h-1 mb-6 range-sm';
}
else if (size === 'large') {
    inputClass += 'h-3 range-lg';
}
else {
    inputClass += 'h-2 mb-6';
}
</script>

<input
	{...$$restProps}
	{id}
	name={id}
	type="range"
	{min}
	{max}
	bind:value
	{step}
	class={inputClass}
/>
